"use client";

import React, { useState, useMemo, useEffect, useRef } from "react";
import { 
  ChevronLeft, ChevronRight, Plus, Trash2, Copy, 
  Check, Save, Wand2, Calendar, Lock, Palmtree, 
  AlertTriangle, X, History, Clock, ChevronDown, 
  Briefcase, MoreHorizontal, FileText, Layout
} from "lucide-react";

/* ---------------- 1. MOCK DATA & CONFIG ---------------- */
const HOLIDAYS = ["2026-01-26"]; 
const APPROVED_LEAVES = ["2026-01-27"]; 

const PROJECTS = [
    { id: "p1", name: "Internal / Admin", code: "INT-001", color: "bg-slate-500", billable: false },
    { id: "p2", name: "Acme Corp: Redesign", code: "ACM-102", color: "bg-blue-600", billable: true },
    { id: "p3", name: "Globex: Mobile App", code: "GLO-404", color: "bg-indigo-600", billable: true },
    { id: "p4", name: "Stark Ind: Consulting", code: "STK-999", color: "bg-amber-600", billable: true },
];

/* ---------------- 2. TYPES ---------------- */
type Status = "DRAFT" | "SUBMITTED" | "APPROVED";

interface DayEntry {
    id: string;
    projectId: string;
    hours: number;
    minutes: number;
    notes: string;
}

interface WeekData {
    status: Status;
    lastSaved: Date | null;
    entries: Record<string, DayEntry[]>;
}

type TimesheetDB = Record<string, WeekData>;

/* ---------------- 3. HELPERS ---------------- */
const formatDate = (d: Date) => d.toISOString().split("T")[0];
const addDays = (d: Date, days: number) => {
    const nd = new Date(d);
    nd.setDate(nd.getDate() + days);
    return nd;
};
const startOfWeek = (date: Date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    d.setDate(diff);
    d.setHours(0, 0, 0, 0);
    return d;
};
const formatDuration = (h: number, m: number) => {
    if (h === 0 && m === 0) return "0h";
    return m > 0 ? `${h}h ${m}m` : `${h}h`;
};

/* ---------------- 4. MAIN COMPONENT ---------------- */
export default function CompleteTimesheet() {
    // 1. Setup Initial State with some MOCK HISTORY
    // We create a past week that is already SUBMITTED so you can see the feature working.
    const today = new Date("2026-01-26"); // Freezing time for demo
    const lastWeekStart = addDays(startOfWeek(today), -7);
    
    const [currentWeekStart, setCurrentWeekStart] = useState<Date>(startOfWeek(today));
    
    const [db, setDb] = useState<TimesheetDB>({
        // Current Week (Draft)
        [formatDate(startOfWeek(today))]: { 
            status: "DRAFT", 
            lastSaved: new Date(), 
            entries: {} 
        },
        // Last Week (Submitted)
        [formatDate(lastWeekStart)]: { 
            status: "SUBMITTED", 
            lastSaved: new Date(), 
            entries: {
                [formatDate(addDays(lastWeekStart, 0))]: [{ id: "mock1", projectId: "p2", hours: 8, minutes: 0, notes: "Design Sprint" }],
                [formatDate(addDays(lastWeekStart, 1))]: [{ id: "mock2", projectId: "p2", hours: 4, minutes: 30, notes: "Review" }],
            }
        }
    });

    // UI States
    const [selectedDate, setSelectedDate] = useState<string | null>(null); 
    const [activeMenu, setActiveMenu] = useState<'import' | 'history' | null>(null);
    const [isSubmitModalOpen, setIsSubmitModalOpen] = useState(false);
    const [toast, setToast] = useState<{ type: 'success' | 'error', msg: string } | null>(null);
    const [isSaving, setIsSaving] = useState(false);

    // Helpers
    const currentWeekKey = formatDate(currentWeekStart);
    const currentData = db[currentWeekKey] || { status: "DRAFT", lastSaved: null, entries: {} };
    const isLocked = currentData.status !== "DRAFT";

    // Click Outside Handler for Menus
    const menuRef = useRef<HTMLDivElement>(null);
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setActiveMenu(null);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    // Auto-dismiss toast
    useEffect(() => {
        if (toast) {
            const timer = setTimeout(() => setToast(null), 3000);
            return () => clearTimeout(timer);
        }
    }, [toast]);

    /* --- DATA CALCULATIONS --- */
    const days = useMemo(() => {
        return Array.from({ length: 7 }).map((_, i) => {
            const d = addDays(currentWeekStart, i);
            const dateStr = formatDate(d);
            return {
                label: d.toLocaleDateString("en-US", { weekday: "short" }),
                fullLabel: d.toLocaleDateString("en-US", { weekday: "long", month: 'short', day: 'numeric' }),
                date: dateStr,
                dayNum: d.getDate(),
                isWeekend: i === 5 || i === 6,
                isHoliday: HOLIDAYS.includes(dateStr),
                isLeave: APPROVED_LEAVES.includes(dateStr),
                entries: currentData.entries[dateStr] || []
            };
        });
    }, [currentWeekStart, currentData]);

    const stats = useMemo(() => {
        let totalMins = 0;
        let billableMins = 0;
        Object.values(currentData.entries).forEach(dayEntries => {
            dayEntries.forEach(e => {
                const mins = (e.hours * 60) + e.minutes;
                totalMins += mins;
                if (PROJECTS.find(p => p.id === e.projectId)?.billable) billableMins += mins;
            });
        });
        return { 
            total: (totalMins / 60).toFixed(1), 
            billable: (billableMins / 60).toFixed(1),
            utilization: Math.min(100, (totalMins / 2400) * 100)
        };
    }, [currentData]);

    /* --- ACTIONS --- */
    const updateDb = (fn: (prev: TimesheetDB) => TimesheetDB) => setDb(prev => fn(prev));

    const handleNavigate = (dir: 'prev' | 'next') => {
        setCurrentWeekStart(prev => addDays(prev, dir === 'next' ? 7 : -7));
    };

    const handleJumpToWeek = (dateStr: string) => {
        setCurrentWeekStart(new Date(dateStr));
        setActiveMenu(null);
    };

    const handleSaveDraft = () => {
        setIsSaving(true);
        setTimeout(() => {
            updateDb(prev => ({
                ...prev,
                [currentWeekKey]: { ...currentData, lastSaved: new Date() }
            }));
            setIsSaving(false);
            setToast({ type: 'success', msg: "Draft saved successfully" });
        }, 600);
    };

    const handleSubmit = () => {
        updateDb(prev => ({
            ...prev,
            [currentWeekKey]: { ...currentData, status: "SUBMITTED" }
        }));
        setIsSubmitModalOpen(false);
        setToast({ type: 'success', msg: "Timesheet Submitted" });
    };

    const handleWithdraw = () => {
        updateDb(prev => ({
            ...prev,
            [currentWeekKey]: { ...currentData, status: "DRAFT" }
        }));
        setToast({ type: 'success', msg: "Withdrawn to Draft" });
    };

    /* --- IMPORT / COPY LOGIC --- */
    const handleCopyWeek = (sourceWeekKey: string) => {
        if (isLocked) return;
        const sourceEntries = db[sourceWeekKey]?.entries || {};
        
        // Clone logic
        const newEntries: Record<string, DayEntry[]> = {};
        days.forEach((day, index) => {
            if (day.isHoliday || day.isLeave) return; // Governance check
            
            const sourceDate = addDays(new Date(sourceWeekKey), index);
            const sourceDayEntries = sourceEntries[formatDate(sourceDate)] || [];

            if (sourceDayEntries.length > 0) {
                newEntries[day.date] = sourceDayEntries.map(e => ({ ...e, id: crypto.randomUUID() }));
            }
        });

        updateDb(prev => ({
            ...prev,
            [currentWeekKey]: { ...currentData, entries: newEntries }
        }));
        setActiveMenu(null);
        setToast({ type: 'success', msg: "Imported entries successfully" });
    };

    /* --- ENTRY MANAGEMENT --- */
    const addEntry = (date: string) => {
        const newEntry = { id: crypto.randomUUID(), projectId: PROJECTS[0].id, hours: 0, minutes: 0, notes: "" };
        updateDb(prev => {
            const week = prev[currentWeekKey] || { status: 'DRAFT', entries: {} };
            return {
                ...prev,
                [currentWeekKey]: {
                    ...week,
                    entries: { ...week.entries, [date]: [...(week.entries[date] || []), newEntry] }
                }
            };
        });
    };

    const updateEntry = (date: string, id: string, field: keyof DayEntry, val: any) => {
        let cleanVal = val;
        if (field === 'hours') cleanVal = Math.max(0, parseInt(val) || 0);
        if (field === 'minutes') cleanVal = Math.max(0, Math.min(59, parseInt(val) || 0));

        updateDb(prev => {
            const week = prev[currentWeekKey];
            const updated = week.entries[date].map(e => e.id === id ? { ...e, [field]: cleanVal } : e);
            return { ...prev, [currentWeekKey]: { ...week, entries: { ...week.entries, [date]: updated } } };
        });
    };

    const deleteEntry = (date: string, id: string) => {
        updateDb(prev => {
            const week = prev[currentWeekKey];
            return { ...prev, [currentWeekKey]: { ...week, entries: { ...week.entries, [date]: week.entries[date].filter(e => e.id !== id) } } };
        });
    };

    return (
        <div className="min-h-screen bg-[#F8F9FC] dark:bg-[#0B0F19] text-slate-900 dark:text-slate-100 font-sans pb-32">
            
            {/* 1. TOP NAVIGATION & HEADER */}
            <div className="bg-white dark:bg-[#11151F] border-b border-slate-200 dark:border-slate-800 sticky top-0 z-30 shadow-sm">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
                    
                    {/* Left: Brand & Nav */}
                    <div className="flex items-center gap-6">
                        <div className="flex items-center gap-2">
                            <div className="p-1.5 bg-blue-600 text-white rounded-lg"><Clock size={18} /></div>
                            <span className="font-bold text-lg hidden sm:block">Timesheet</span>
                        </div>

                        {/* Week Navigator Group */}
                        <div className="flex items-center bg-slate-100 dark:bg-slate-800 rounded-lg p-1" ref={menuRef}>
                            <button onClick={() => handleNavigate('prev')} className="p-1.5 hover:bg-white dark:hover:bg-slate-700 rounded-md transition-all"><ChevronLeft size={16}/></button>
                            
                            {/* History Dropdown Trigger */}
                            <div className="relative">
                                <button 
                                    onClick={() => setActiveMenu(activeMenu === 'history' ? null : 'history')}
                                    className="px-4 py-1 text-sm font-bold flex items-center gap-2 hover:bg-white dark:hover:bg-slate-700 rounded-md transition-all tabular-nums"
                                >
                                    <Calendar size={14} className="text-slate-500" />
                                    {days[0].date} - {days[6].date}
                                    <ChevronDown size={12} className={`text-slate-400 transition-transform ${activeMenu === 'history' ? 'rotate-180' : ''}`} />
                                </button>

                                {/* History Dropdown Panel */}
                                {activeMenu === 'history' && (
                                    <div className="absolute top-full left-0 mt-2 w-72 bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-xl shadow-xl z-50 overflow-hidden animate-in fade-in zoom-in-95">
                                        <div className="p-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50">
                                            <span className="text-[10px] font-black uppercase text-slate-400">Recent Weeks</span>
                                        </div>
                                        <div className="max-h-60 overflow-y-auto">
                                            {Array.from({ length: 8 }).map((_, i) => {
                                                const d = addDays(startOfWeek(new Date()), -(i) * 7);
                                                const dStr = formatDate(d);
                                                const weekStatus = db[dStr]?.status || "NOT_STARTED";
                                                const isCurrent = dStr === currentWeekKey;

                                                return (
                                                    <button 
                                                        key={i}
                                                        onClick={() => handleJumpToWeek(dStr)}
                                                        className={`w-full flex items-center justify-between px-4 py-3 border-b border-slate-50 dark:border-slate-800/50 last:border-0 hover:bg-slate-50 dark:hover:bg-slate-800 ${isCurrent ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}`}
                                                    >
                                                        <div>
                                                            <div className={`text-xs font-bold ${isCurrent ? 'text-blue-600' : 'text-slate-700 dark:text-slate-200'}`}>Week of {d.toLocaleDateString()}</div>
                                                            <div className="text-[10px] text-slate-400 mt-0.5">{isCurrent ? "Currently Viewing" : "Navigate to view"}</div>
                                                        </div>
                                                        <span className={`text-[9px] font-black px-2 py-0.5 rounded ${
                                                            weekStatus === 'SUBMITTED' ? 'bg-blue-100 text-blue-700' : 
                                                            weekStatus === 'DRAFT' ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-500'
                                                        }`}>
                                                            {weekStatus === 'NOT_STARTED' ? 'EMPTY' : weekStatus}
                                                        </span>
                                                    </button>
                                                )
                                            })}
                                        </div>
                                    </div>
                                )}
                            </div>

                            <button onClick={() => handleNavigate('next')} className="p-1.5 hover:bg-white dark:hover:bg-slate-700 rounded-md transition-all"><ChevronRight size={16}/></button>
                        </div>
                    </div>

                    {/* Right: Actions */}
                    <div className="flex items-center gap-3">
                        {/* Import / Copy Menu */}
                        <div className="relative" ref={menuRef}>
                            <button 
                                onClick={() => setActiveMenu(activeMenu === 'import' ? null : 'import')}
                                disabled={isLocked}
                                className="hidden md:flex items-center gap-2 px-3 py-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg text-xs font-bold text-slate-600 dark:text-slate-300 hover:border-blue-500 transition-all disabled:opacity-50"
                            >
                                <Copy size={14} className="text-blue-500" /> Copy from... <ChevronDown size={12} />
                            </button>

                            {activeMenu === 'import' && (
                                <div className="absolute top-full right-0 mt-2 w-64 bg-white dark:bg-[#11151F] border border-slate-200 dark:border-slate-800 rounded-xl shadow-xl z-50 overflow-hidden animate-in fade-in zoom-in-95">
                                    <div className="p-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900/50">
                                        <span className="text-[10px] font-black uppercase text-slate-400">Copy From Past 12 Weeks</span>
                                    </div>
                                    <div className="max-h-60 overflow-y-auto">
                                        {Array.from({ length: 12 }).map((_, i) => {
                                            const d = addDays(currentWeekStart, -(i + 1) * 7);
                                            const dStr = formatDate(d);
                                            const hasData = db[dStr] && Object.keys(db[dStr].entries).length > 0;
                                            
                                            return (
                                                <button 
                                                    key={i}
                                                    onClick={() => handleCopyWeek(dStr)}
                                                    disabled={!hasData}
                                                    className="w-full text-left px-4 py-3 hover:bg-slate-50 dark:hover:bg-slate-800 text-xs font-medium border-b border-slate-50 dark:border-slate-800/50 last:border-0 disabled:opacity-50 disabled:cursor-not-allowed"
                                                >
                                                    <div className="flex justify-between">
                                                        <span className="font-bold text-slate-700 dark:text-slate-200">{d.toLocaleDateString()}</span>
                                                        {hasData && <span className="text-[9px] bg-emerald-50 text-emerald-600 px-1.5 py-0.5 rounded">Has Data</span>}
                                                    </div>
                                                    <div className="text-[10px] text-slate-400 mt-0.5">
                                                        {hasData ? "Click to import entries" : "No entries to copy"}
                                                    </div>
                                                </button>
                                            )
                                        })}
                                    </div>
                                </div>
                            )}
                        </div>

                        <div className="h-6 w-[1px] bg-slate-200 dark:bg-slate-700 mx-2 hidden md:block" />

                        {/* Status Indicator */}
                        <div className={`px-3 py-1.5 rounded-full text-xs font-bold uppercase flex items-center gap-2 ${isLocked ? 'bg-blue-50 text-blue-700 border border-blue-100' : 'bg-amber-50 text-amber-700 border border-amber-100'}`}>
                            {isLocked ? <Lock size={12} /> : <Wand2 size={12} />}
                            {currentData.status}
                        </div>
                    </div>
                </div>
            </div>

            {/* 2. MAIN CONTENT AREA */}
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
                
                {/* Stats Cards */}
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                    <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                        <p className="text-[10px] font-black uppercase text-slate-400">Total Hours</p>
                        <div className="text-2xl font-black text-slate-900 dark:text-white mt-1">{stats.total}</div>
                        <div className="w-full bg-slate-100 h-1.5 rounded-full mt-3 overflow-hidden">
                            <div className="bg-blue-600 h-full transition-all duration-500" style={{ width: `${stats.utilization}%` }} />
                        </div>
                    </div>
                    <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm">
                        <p className="text-[10px] font-black uppercase text-slate-400 flex items-center gap-1"><History size={12}/> Billable</p>
                        <div className="text-2xl font-black text-emerald-600 mt-1">{stats.billable}</div>
                    </div>
                    {/* Add more stats as needed */}
                </div>

                {/* THE GRID */}
                <div className="grid grid-cols-1 md:grid-cols-7 gap-4">
                    {days.map((d) => {
                        const totalMins = d.entries.reduce((a, b) => a + (b.hours * 60) + b.minutes, 0);
                        const totalHours = Math.floor(totalMins / 60);
                        const totalMinutes = totalMins % 60;
                        
                        return (
                            <div 
                                key={d.date}
                                className={`
                                    relative min-h-[240px] rounded-2xl border transition-all duration-300 flex flex-col group
                                    ${d.isBlocked || isLocked 
                                        ? "bg-slate-50 dark:bg-slate-900/50 border-slate-200 dark:border-slate-800" 
                                        : "bg-white dark:bg-[#11151F] border-slate-200 dark:border-slate-800 hover:border-blue-400 hover:shadow-lg"
                                    }
                                `}
                            >
                                {/* Card Header */}
                                <div className="p-3 border-b border-slate-100 dark:border-slate-800/50 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/30 rounded-t-2xl">
                                    <div>
                                        <div className="text-[10px] font-black uppercase text-slate-400">{d.label}</div>
                                        <div className={`text-xl font-black ${d.isBlocked ? 'text-slate-300' : 'text-slate-800 dark:text-white'}`}>{d.dayNum}</div>
                                    </div>
                                    {d.isHoliday && <Lock size={16} className="text-purple-400" />}
                                    {d.isLeave && <Palmtree size={16} className="text-amber-400" />}
                                    {!d.isBlocked && totalMins > 0 && (
                                        <span className="text-[10px] font-black px-2 py-0.5 rounded bg-slate-100 text-slate-600">
                                            {formatDuration(totalHours, totalMinutes)}
                                        </span>
                                    )}
                                </div>

                                {/* Entries Area */}
                                <div 
                                    onClick={() => !d.isBlocked && !isLocked && setSelectedDate(d.date)}
                                    className={`flex-1 p-2 space-y-2 overflow-y-auto max-h-[300px] custom-scrollbar ${!d.isBlocked && !isLocked ? 'cursor-pointer' : ''}`}
                                >
                                    {d.entries.map(e => {
                                        const proj = PROJECTS.find(p => p.id === e.projectId);
                                        return (
                                            <div key={e.id} className="p-2 bg-white dark:bg-slate-900 rounded-lg border border-slate-100 dark:border-slate-800 shadow-sm">
                                                <div className="flex justify-between mb-1">
                                                    <div className={`w-1.5 h-1.5 rounded-full ${proj?.color}`} />
                                                    <span className="text-[10px] font-bold">{formatDuration(e.hours, e.minutes)}</span>
                                                </div>
                                                <p className="text-[10px] text-slate-500 font-medium truncate">{proj?.code}</p>
                                            </div>
                                        )
                                    })}
                                    
                                    {!d.isBlocked && !isLocked && d.entries.length === 0 && (
                                        <div className="h-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                            <div className="w-8 h-8 rounded-full bg-blue-50 text-blue-500 flex items-center justify-center">
                                                <Plus size={16} />
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>
                        )
                    })}
                </div>
            </div>

            {/* 3. FOOTER ACTIONS */}
            <div className="fixed bottom-0 w-full bg-white dark:bg-[#11151F] border-t border-slate-200 dark:border-slate-800 p-4 z-40 flex justify-center items-center gap-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
                {isLocked ? (
                    <button onClick={handleWithdraw} className="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 px-8 py-3 rounded-full font-bold text-sm hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors flex items-center gap-2">
                         <Lock size={16} /> Week Submitted - Click to Withdraw
                    </button>
                ) : (
                    <>
                        <button 
                            onClick={handleSaveDraft}
                            disabled={isSaving}
                            className="px-8 py-3 rounded-full font-bold text-sm border border-slate-200 text-slate-600 hover:bg-slate-50 flex items-center gap-2 transition-all"
                        >
                            {isSaving ? <span className="animate-pulse">Saving...</span> : <><Save size={16} /> Save Draft</>}
                        </button>
                        <button 
                            onClick={() => setIsSubmitModalOpen(true)} 
                            disabled={stats.total === "0.0"}
                            className="bg-blue-600 text-white px-8 py-3 rounded-full font-bold text-sm hover:bg-blue-700 transition-all shadow-lg shadow-blue-500/30 disabled:opacity-50 disabled:shadow-none flex items-center gap-2"
                        >
                            <Check size={18} /> Submit Timesheet
                        </button>
                    </>
                )}
            </div>

            {/* --- TOAST NOTIFICATION --- */}
            {toast && (
                <div className={`fixed bottom-24 left-1/2 -translate-x-1/2 px-6 py-3 rounded-full font-bold shadow-xl flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4 z-50 ${toast.type === 'success' ? 'bg-emerald-600 text-white' : 'bg-red-600 text-white'}`}>
                    {toast.type === 'success' ? <Check size={18} /> : <AlertTriangle size={18} />}
                    {toast.msg}
                </div>
            )}

            {/* --- SLIDE-OVER DRAWER --- */}
            {selectedDate && (
                <div className="fixed inset-0 z-50 flex justify-end">
                    <div className="absolute inset-0 bg-slate-900/30 backdrop-blur-sm" onClick={() => setSelectedDate(null)} />
                    <div className="relative w-full max-w-md bg-white dark:bg-[#11151F] h-full shadow-2xl flex flex-col animate-in slide-in-from-right duration-300">
                        <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50 dark:bg-slate-900">
                            <div>
                                <h2 className="text-xl font-black text-slate-900 dark:text-white">
                                    {new Date(selectedDate).toLocaleDateString("en-US", { weekday: 'long' })}
                                </h2>
                                <p className="text-sm font-medium text-slate-500">{selectedDate}</p>
                            </div>
                            <button onClick={() => setSelectedDate(null)} className="p-2 hover:bg-slate-200 dark:hover:bg-slate-800 rounded-full transition-colors"><X size={20} className="text-slate-500" /></button>
                        </div>
                        <div className="flex-1 overflow-y-auto p-6 space-y-6">
                            <div className="space-y-4">
                                {(currentData.entries[selectedDate] || []).map((e, idx) => (
                                    <div key={e.id} className="group bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-4 shadow-sm hover:border-blue-400 transition-colors relative">
                                        <div className="flex gap-3 mb-4">
                                            <div className="flex-1">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Project</label>
                                                <select value={e.projectId} onChange={(ev) => updateEntry(selectedDate, e.id, 'projectId', ev.target.value)} className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none">
                                                    {PROJECTS.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                                                </select>
                                            </div>
                                            <div className="w-14">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Hrs</label>
                                                <input type="number" min="0" max="23" value={e.hours} onChange={(ev) => updateEntry(selectedDate, e.id, 'hours', ev.target.value)} className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none" />
                                            </div>
                                            <div className="w-14">
                                                <label className="text-[10px] font-bold uppercase text-slate-400 mb-1 block">Mins</label>
                                                <input type="number" min="0" max="59" value={e.minutes} onChange={(ev) => updateEntry(selectedDate, e.id, 'minutes', ev.target.value)} className="w-full text-sm font-bold bg-transparent border-b border-slate-200 dark:border-slate-700 pb-1 focus:border-blue-500 outline-none" />
                                            </div>
                                        </div>
                                        <input type="text" placeholder="What did you work on?" value={e.notes} onChange={(ev) => updateEntry(selectedDate, e.id, 'notes', ev.target.value)} className="w-full text-sm bg-slate-50 dark:bg-slate-800 p-3 rounded-lg outline-none focus:ring-2 focus:ring-blue-500/20" />
                                        <button onClick={() => deleteEntry(selectedDate, e.id)} className="absolute -top-2 -right-2 bg-white dark:bg-slate-800 text-slate-400 hover:text-red-500 p-1.5 rounded-full shadow-sm border border-slate-200 dark:border-slate-700 opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={14} /></button>
                                    </div>
                                ))}
                            </div>
                            <button onClick={() => addEntry(selectedDate)} className="w-full py-4 border-2 border-dashed border-slate-300 dark:border-slate-700 rounded-xl flex items-center justify-center gap-2 text-slate-500 font-bold hover:border-blue-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-slate-800 transition-all"><Plus size={20} /> Add Activity</button>
                        </div>
                        <div className="p-4 border-t border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-900">
                             <button onClick={() => setSelectedDate(null)} className="w-full bg-slate-900 text-white font-bold py-3 rounded-xl hover:bg-slate-800 transition-colors">Done</button>
                        </div>
                    </div>
                </div>
            )}

            {/* --- SUBMIT MODAL --- */}
            {isSubmitModalOpen && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm">
                    <div className="bg-white dark:bg-slate-900 rounded-2xl p-8 max-w-sm w-full text-center shadow-2xl animate-in zoom-in-95">
                        <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mx-auto mb-4"><Lock size={32} /></div>
                        <h3 className="text-xl font-bold text-slate-900 dark:text-white mb-2">Confirm Submission</h3>
                        <p className="text-sm text-slate-500 mb-6">This will lock the week of <strong>{currentWeekKey}</strong>. You cannot edit entries after this.</p>
                        <div className="flex gap-3 justify-center">
                            <button onClick={() => setIsSubmitModalOpen(false)} className="px-5 py-2 rounded-lg font-bold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800">Cancel</button>
                            <button onClick={handleSubmit} className="px-6 py-2 rounded-lg font-bold bg-blue-600 text-white hover:bg-blue-700">Confirm</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}